def check(output, ctx):
    try:
        d = parse_json(output)
        if not isinstance(d, dict):
            return True
        toks = ctx['text'].split()
        low = [x.lower() for x in toks]
        for k in ["person", "location", "organization", "else"]:
            v = d.get(k, [])
            if not isinstance(v, list):
                continue
            for e in v:
                if not isinstance(e, str):
                    continue
                et = e.strip().lower().split()
                n = len(et)
                if n == 0:
                    continue
                occ = [i for i in range(len(toks) - n + 1) if low[i:i+n] == et]
                if not occ:
                    continue
                if not any(any(c.isupper() for c in " ".join(toks[i:i+n])) for i in occ):
                    return False
        return True
    except Exception:
        return True

def check(output: str, ctx: dict) -> bool:
    obj = parse_json(output)
    if obj is None:
        return False
    tokens = ctx['text'].split()
    contains_named_entity = any(token[0].isupper() for token in tokens if token.isalpha())
    if contains_named_entity:
        return any(obj[field] for field in ['person', 'location', 'organization', 'else'])
    return True

